SELECT sku, gtin, name, pack, price_inr
FROM store.products
WHERE name ILIKE '%atta%' OR name ILIKE '%wheat%';

SELECT table_name
FROM information_schema.tables
WHERE table_schema = 'store' AND table_name LIKE '%customer%';

SELECT SUM(net_inr) as total_net_upi
FROM payments.upi_settlements
WHERE settlement_date >= '2026-06-01' AND settlement_date <= '2026-06-30';

SELECT COUNT(DISTINCT order_id) AS distinct_orders
FROM store.store_orders
WHERE created_ts >= '2026-06-01' AND created_ts < '2026-07-01';

SELECT p.sku, p.name, p.pack, p.price_inr, p.cost_inr
FROM store.products p
WHERE p.name ILIKE '%atta%' AND p.pack ILIKE '%5%kg%';

SELECT p.sku, p.name, p.pack, p.price_inr, p.cost_inr, p.flow
FROM store.products p
WHERE p.name ILIKE '%milk%' OR p.name ILIKE '%toned%';

SELECT sku, name, pack, price_inr, cost_inr, flow
FROM store.products
WHERE name ILIKE '%milk%' OR name ILIKE '%dairy%' OR name ILIKE '%curd%' OR name ILIKE '%yogurt%';
